SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',(to_jsonb(c)-ARRAY['relfilenode','relpages','reltuples','relallvisible','relfrozenxid','relminmxid']),'identity',to_jsonb(pg_identify_object('pg_class'::regclass,c.oid,0)),'namespace',n.nspname,'owner',pg_get_userbyid(c.relowner),'access_method',am.amname,'tablespace',ts.spcname,'row_type',CASE WHEN c.reltype<>0 THEN to_jsonb(pg_identify_object('pg_type'::regclass,c.reltype,0)) END,'toast_parent',(SELECT to_jsonb(pg_identify_object('pg_class'::regclass,p.oid,0)) FROM pg_class p WHERE p.reltoastrelid=c.oid),'toast_index_parent',(SELECT to_jsonb(pg_identify_object('pg_class'::regclass,p.oid,0)) FROM pg_index i JOIN pg_class p ON p.reltoastrelid=i.indrelid WHERE i.indexrelid=c.oid),'partition_bound',pg_get_expr(c.relpartbound,c.oid,false)) ORDER BY c.oid),'[]'::jsonb) AS payload FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_am am ON am.oid=c.relam LEFT JOIN pg_tablespace ts ON ts.oid=c.reltablespace WHERE c.oid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture